import '@servicenow/sdk/global'
import { Flow, wfa, action, trigger } from '@servicenow/sdk/automation'

// ForEach test with identifier datapill (not property access)
// This tests the ForEachItemShape type annotation fix
Flow(
    {
        $id: Now.ID['foreach_datapill_identifier_test'],
        name: 'ForEach Data Pill Identifier Test',
        description: 'Test that forEach item identifier datapills include type annotations',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['foreach_identifier_trigger'] },
        {
            table: 'problem',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Lookup users to iterate over
        const users = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_users'],
                annotation: 'Get users',
            },
            {
                table: 'sys_user',
                conditions: 'active=true',
            }
        )

        wfa.flowLogic.forEach(
            wfa.dataPill(users.Records, 'array.object'),
            { $id: Now.ID['foreach_users'], annotation: 'Iterate users' },
            (item) => {
                // Test 1: Using item property access with type annotation
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_item_property'],
                        annotation: 'Log item property',
                    },
                    {
                        log_level: 'info',
                        log_message: `User Name: ${wfa.dataPill(item.name, 'string')}`,
                    }
                )

                // Test 2: Using just the item identifier with type annotation
                // This tests the ForEachItemShape bug fix
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_item_identifier'],
                        annotation: 'Log item identifier',
                    },
                    {
                        log_level: 'info',
                        log_message: `User: ${wfa.dataPill(item, 'reference')}`,
                    }
                )
            }
        )
    }
)
